import React from 'react';
import { Pressable, ScrollView, Text, View } from 'react-native';
import type { CatalogProduct } from '../../domain/catalog';
import { PosHeader } from '../components/PosHeader';
import { PosQuickActions } from '../components/PosQuickActions';

export const SellScreen = ({
    cashierName,
    catalog,
    cartCount,
    activeShiftId,
    syncStatusLabel,
    storageMode,
    hardwareMessage,
    onAddToCart,
    onOpenCart,
    onOpenHistory,
    onOpenReceipt,
    onOpenShift,
    onOpenCloseShift,
    onOpenSyncCenter
}: {
    cashierName: string;
    catalog: CatalogProduct[];
    cartCount: number;
    activeShiftId: string | null;
    syncStatusLabel: string;
    storageMode: 'memory' | 'sqlite';
    hardwareMessage: string;
    onAddToCart: (product: CatalogProduct) => void;
    onOpenCart: () => void;
    onOpenHistory: () => void;
    onOpenReceipt: () => void;
    onOpenShift: () => void;
    onOpenCloseShift: () => void;
    onOpenSyncCenter: () => void;
}) => (
    <View style={{ flex: 1, backgroundColor: '#F8FAFC' }}>
        <PosHeader
            title="POS Catalog"
            subtitle={`Cashier: ${cashierName || 'Cashier'}${activeShiftId ? ` | Shift ${activeShiftId}` : ' | Shift Closed'}`}
            statusPills={[
                { label: activeShiftId ? 'Shift Open' : 'Shift Closed', tone: activeShiftId ? 'success' : 'warning' },
                { label: `Cart ${cartCount}` },
                { label: `Sync ${syncStatusLabel}` },
                { label: storageMode === 'sqlite' ? 'Offline SQLite' : 'Memory Fallback', tone: storageMode === 'sqlite' ? 'success' : 'warning' }
            ]}
        />
        <View style={{ paddingHorizontal: 20, paddingBottom: 12 }}>
            <Text style={{ color: '#475569' }}>{hardwareMessage}</Text>
        </View>
        <PosQuickActions
            onCheckout={onOpenCart}
            onHistory={onOpenHistory}
            onReceipt={onOpenReceipt}
            onShift={onOpenShift}
            onCloseShift={onOpenCloseShift}
            onSyncCenter={onOpenSyncCenter}
        />
        <ScrollView contentContainerStyle={{ padding: 20 }}>
            {catalog.map((product) => (
                <Pressable
                    key={product.itemId}
                    onPress={() => onAddToCart(product)}
                    style={{ backgroundColor: '#FFFFFF', borderRadius: 8, padding: 16, marginBottom: 12, borderWidth: 1, borderColor: '#E2E8F0' }}
                >
                    <Text style={{ fontSize: 18, fontWeight: '700', color: '#0F172A' }}>{product.itemName}</Text>
                    <Text style={{ marginTop: 4, color: '#475569' }}>{product.categoryName}</Text>
                    <Text style={{ marginTop: 8, color: '#0F766E', fontWeight: '700' }}>PHP {product.price.toFixed(2)}</Text>
                </Pressable>
            ))}
        </ScrollView>
    </View>
);
