import { create } from 'zustand';
import { initializeHardwarePosDependencies } from './dependencies';
import { mockCatalog } from './mockCatalog';
import type { CatalogProduct } from '../domain/catalog';
import type { LocalCheckoutInput, LocalTransactionLineInput } from '../domain/checkout';
import type { PendingHistorySnapshot } from '../services/pendingHistoryService';
import { standalonePosHardware } from '../native/standalonePosHardware';
import { standalonePosSync } from '../native/standalonePosSync';

type HardwareScreen =
    | 'splash'
    | 'login_unlock'
    | 'shift_open'
    | 'sell_screen'
    | 'cart'
    | 'receipt'
    | 'history'
    | 'sync_center'
    | 'close_shift';

interface CartLine {
    product: CatalogProduct;
    quantity: number;
}

interface HardwarePosState {
    screen: HardwareScreen;
    isOnline: boolean;
    hardwareReady: boolean;
    deviceId: string;
    cashierName: string;
    cashierId: number | null;
    activeShiftId: string | null;
    catalog: CatalogProduct[];
    cart: CartLine[];
    pendingHistory: PendingHistorySnapshot | null;
    lastReceipt: {
        localTransactionId: string;
        cashierName: string;
        shiftId: string;
        createdAtLocal: string;
        total: number;
        paymentType: string;
        lines: Array<{ name: string; quantity: number; total: number }>;
        syncState: 'pending_sync' | 'synced';
    } | null;
    syncStatusLabel: string;
    lastSyncMessage: string;
    storageMode: 'memory' | 'sqlite';
    hardwareMessage: string;
    hardwareDiagnostics: Record<string, unknown> | null;
    loginBaseUrl: string;
    companyToken: string;
    loginEmail: string;
    loading: boolean;
    bootstrap(): Promise<void>;
    unlockCashier(input: {
        baseUrl: string;
        companyToken: string;
        email: string;
        password: string;
    }): Promise<void>;
    openShift(openingCash: number): Promise<void>;
    addToCart(product: CatalogProduct): void;
    goToCart(): void;
    backToSell(): void;
    openReceipt(): void;
    openHistory(): Promise<void>;
    openSyncCenter(): Promise<void>;
    openCloseShift(): void;
    commitCheckout(): Promise<void>;
    runManualSync(): Promise<void>;
    printLastReceipt(): Promise<void>;
    openDrawer(): Promise<void>;
    loadHardwareDiagnostics(): Promise<void>;
    closeShift(): Promise<void>;
}

const toSyncStatusLabel = (successfulSyncCountToday: number): string => {
    if (successfulSyncCountToday <= 0) return '0/2';
    if (successfulSyncCountToday === 1) return '1/2';
    return '2/2';
};

const getDeps = () => initializeHardwarePosDependencies({
    deviceId: 'IMIN-DEVICE-01'
});

const buildCheckoutInput = (
    deviceId: string,
    cashierName: string,
    shiftId: string,
    cart: CartLine[]
): LocalCheckoutInput => {
    const createdAtLocal = new Date().toISOString();
    const lines: LocalTransactionLineInput[] = cart.map((entry, index) => ({
        lineId: `${deviceId}-line-${Date.now()}-${index}`,
        itemId: entry.product.itemId,
        itemName: entry.product.itemName,
        quantity: entry.quantity,
        unitPrice: entry.product.price,
        discounts: 0,
        fees: 0,
        vatRelevantAmount: entry.product.price * entry.quantity,
        barcodeMetadata: entry.product.barcode ? { code: entry.product.barcode } : null
    }));
    const grandTotal = lines.reduce((sum, line) => sum + (line.unitPrice * line.quantity), 0);

    return {
        localTransactionId: `${deviceId}-sale-${Date.now()}`,
        idempotencyKey: `${deviceId}-idem-${Date.now()}`,
        createdAtLocal,
        cashierId: 1,
        shiftId,
        receiptState: 'printed_local_pending_sync',
        lines,
        totals: {
            subtotal: grandTotal,
            discountTotal: 0,
            feeTotal: 0,
            grandTotal,
            vatTotal: grandTotal * 0.12
        },
        pricingSnapshot: {
            source: 'local_catalog_cache'
        },
        paymentSnapshot: {
            payment_type: 'cash',
            cashier_name: cashierName
        },
        customerSnapshot: null
    };
};

export const useHardwarePosStore = create<HardwarePosState>((set, get) => ({
    screen: 'splash',
    isOnline: true,
    hardwareReady: true,
    deviceId: 'IMIN-DEVICE-01',
    cashierName: '',
    cashierId: null,
    activeShiftId: null,
    catalog: [],
    cart: [],
    pendingHistory: null,
    lastReceipt: null,
    syncStatusLabel: '0/2',
    lastSyncMessage: 'No sync executed yet.',
    storageMode: 'memory',
    hardwareMessage: standalonePosHardware.available
        ? 'Native hardware bridge available.'
        : 'Native hardware bridge unavailable in this runtime.',
    hardwareDiagnostics: null,
    loginBaseUrl: 'https://pos.dgfy.ph',
    companyToken: '',
    loginEmail: '',
    loading: false,
    async bootstrap() {
        const deps = await getDeps();
        set({ loading: true, screen: 'splash' });
        let catalog = mockCatalog;
        const persistedSession = await deps.runtimeStateService?.getActiveCashierSession() ?? null;
        const persistedShift = await deps.runtimeStateService?.getActiveShiftState() ?? null;
        const persistedAuthConfig = await deps.runtimeStateService?.getAuthConfig() ?? null;

        if (persistedAuthConfig) {
            deps.configureMobileClient(persistedAuthConfig);
        }

        const currentClient = deps.getMobilePosClient();
        if (currentClient) {
            try {
                const response = await currentClient.getCatalog({ limit: 100 });
                catalog = response.catalog.map((entry, index) => ({
                    itemId: Number(entry.item_id ?? index + 1),
                    itemName: String(entry.item_name ?? entry.name ?? `Item ${index + 1}`),
                    categoryName: String(entry.folder_name ?? 'General'),
                    price: Number(entry.sale_price ?? entry.price ?? 0),
                    barcode: entry.barcode ? String(entry.barcode) : null,
                    imageUrl: null
                }));
            } catch {
                catalog = mockCatalog;
            }
        }

        const pendingHistory = await deps.pendingHistoryService.getSnapshot();
        const syncPolicy = await deps.syncPolicyRepository.getCurrent();
        set({
            catalog,
            pendingHistory,
            storageMode: deps.storageMode,
            syncStatusLabel: toSyncStatusLabel(syncPolicy.successfulSyncCountToday),
            cashierName: persistedSession?.cashierName ?? '',
            cashierId: persistedSession?.cashierId ?? null,
            activeShiftId: persistedShift?.shiftId ?? null,
            loginBaseUrl: persistedAuthConfig?.baseUrl?.replace(/\/api\/v1\/?$/, '') ?? 'https://pos.dgfy.ph',
            companyToken: persistedAuthConfig?.companyToken ?? '',
            loginEmail: '',
            loading: false,
            screen: persistedSession
                ? (persistedShift ? 'sell_screen' : 'shift_open')
                : 'login_unlock',
            hardwareMessage: persistedSession
                ? `Restored cashier ${persistedSession.cashierName}${persistedShift ? ` and shift ${persistedShift.shiftId}` : ''}.`
                : get().hardwareMessage
        });
    },
    async unlockCashier(input) {
        const deps = await getDeps();
        set({ loading: true, hardwareMessage: 'Authenticating cashier...' });
        try {
            const authSession = await deps.authClient.login({
                baseUrl: input.baseUrl,
                companyToken: input.companyToken,
                email: input.email,
                password: input.password
            });

            const normalizedBaseUrl = input.baseUrl.endsWith('/api/v1')
                ? input.baseUrl
                : `${input.baseUrl.replace(/\/+$/, '')}/api/v1`;
            const clientConfig = {
                baseUrl: normalizedBaseUrl,
                authToken: authSession.token,
                companyToken: authSession.companyToken
            };
            deps.configureMobileClient(clientConfig);
            await deps.runtimeStateService?.saveAuthConfig(clientConfig);
            await deps.runtimeStateService?.saveCashierSession({
                sessionId: `session-${Date.now()}`,
                cashierId: authSession.userId || 1,
                cashierName: authSession.username || authSession.email,
                openedAt: new Date().toISOString(),
                status: 'active'
            });

            set({
                cashierName: authSession.username || authSession.email,
                cashierId: authSession.userId || 1,
                loginBaseUrl: input.baseUrl,
                companyToken: input.companyToken,
                loginEmail: input.email,
                hardwareMessage: 'Cashier authenticated and local session cached.',
                loading: false,
                screen: get().activeShiftId ? 'sell_screen' : 'shift_open'
            });
        } catch (error) {
            set({
                loading: false,
                hardwareMessage: error instanceof Error ? error.message : 'Cashier authentication failed.'
            });
        }
    },
    async openShift(openingCash: number) {
        const shiftId = `shift-${Date.now()}`;
        const cashierId = get().cashierId ?? 1;
        const deps = await getDeps();
        await deps.runtimeStateService?.saveShiftState({
            shiftId,
            cashierId,
            openingCashAmount: openingCash,
            openedAt: new Date().toISOString(),
            status: 'open'
        });
        set({
            activeShiftId: shiftId,
            hardwareMessage: `Shift ${shiftId} opened locally.`,
            screen: 'sell_screen'
        });
    },
    addToCart(product: CatalogProduct) {
        const existing = get().cart.find((line) => line.product.itemId === product.itemId);
        if (existing) {
            set({
                cart: get().cart.map((line) => line.product.itemId === product.itemId
                    ? { ...line, quantity: line.quantity + 1 }
                    : line)
            });
            return;
        }

        set({
            cart: [...get().cart, { product, quantity: 1 }]
        });
    },
    goToCart() {
        set({ screen: 'cart' });
    },
    backToSell() {
        set({ screen: 'sell_screen' });
    },
    openReceipt() {
        if (!get().lastReceipt) {
            return;
        }
        set({ screen: 'receipt' });
    },
    async openHistory() {
        const deps = await getDeps();
        const pendingHistory = await deps.pendingHistoryService.getSnapshot();
        set({
            pendingHistory,
            screen: 'history'
        });
    },
    async openSyncCenter() {
        const deps = await getDeps();
        const pendingHistory = await deps.pendingHistoryService.getSnapshot();
        set({
            pendingHistory,
            screen: 'sync_center'
        });
    },
    openCloseShift() {
        set({ screen: 'close_shift' });
    },
    async commitCheckout() {
        const deps = await getDeps();
        const state = get();
        if (!state.activeShiftId || state.cart.length === 0) {
            return;
        }

        const input = buildCheckoutInput(
            state.deviceId,
            state.cashierName,
            state.activeShiftId,
            state.cart
        );
        input.cashierId = state.cashierId ?? 1;

        await deps.localCheckoutJournalService.commitLocalCheckout(input);
        const pendingHistory = await deps.pendingHistoryService.getSnapshot();

        set({
            cart: [],
            pendingHistory,
            lastReceipt: {
                localTransactionId: input.localTransactionId,
                cashierName: state.cashierName,
                shiftId: state.activeShiftId,
                createdAtLocal: input.createdAtLocal,
                total: input.totals.grandTotal,
                paymentType: 'cash',
                lines: input.lines.map((line) => ({
                    name: line.itemName,
                    quantity: line.quantity,
                    total: line.unitPrice * line.quantity
                })),
                syncState: 'pending_sync'
            },
            screen: 'receipt'
        });
    },
    async runManualSync() {
        const deps = await getDeps();
        const outcome = await deps.manualSyncService.run(`sync-${Date.now()}`, new Date());
        const workerStatus = await standalonePosSync.enqueueAuthorizedSync(get().deviceId);
        const pendingHistory = await deps.pendingHistoryService.getSnapshot();
        const currentReceipt = get().lastReceipt;
        set({
            pendingHistory,
            screen: 'sync_center',
            syncStatusLabel: toSyncStatusLabel(outcome.successfulSyncCountToday),
            lastSyncMessage: outcome.outcome === 'blocked_daily_limit'
                ? `Sync blocked until ${outcome.nextAllowedSyncAt ?? 'next business day'}`
                : `Last sync outcome: ${outcome.outcome}${workerStatus.state ? ` | worker ${workerStatus.state}` : ''}`,
            hardwareMessage: outcome.outcome === 'blocked_daily_limit'
                ? `WorkManager authorization blocked until ${outcome.nextAllowedSyncAt ?? 'next business day'}.`
                : `Manual sync completed with outcome ${outcome.outcome}. Authorized worker ${workerStatus.workId || 'unavailable'}.`,
            lastReceipt: currentReceipt && outcome.outcome === 'completed'
                ? { ...currentReceipt, syncState: 'synced' }
                : currentReceipt
        });
    },
    async printLastReceipt() {
        const receipt = get().lastReceipt;
        if (!receipt) {
            set({ hardwareMessage: 'No local receipt is available to print.' });
            return;
        }

        const receiptText = [
            'DGFY POS',
            `Receipt: ${receipt.localTransactionId}`,
            `Cashier: ${receipt.cashierName}`,
            `Shift: ${receipt.shiftId}`,
            `Datetime: ${receipt.createdAtLocal}`,
            '',
            ...receipt.lines.map((line) => `${line.quantity} x ${line.name}  PHP ${line.total.toFixed(2)}`),
            '',
            `TOTAL PHP ${receipt.total.toFixed(2)}`,
            receipt.syncState === 'synced' ? 'Status: Synced' : 'Status: Pending Sync'
        ].join('\n');

        const result = await standalonePosHardware.printReceipt(receiptText, true);
        set({ hardwareMessage: result.message });
    },
    async openDrawer() {
        const receipt = get().lastReceipt;
        const result = await standalonePosHardware.openCashDrawer(
            'manual_open',
            receipt ? { localTransactionId: receipt.localTransactionId } : null
        );
        set({ hardwareMessage: result.message });
    },
    async loadHardwareDiagnostics() {
        const diagnostics = await standalonePosHardware.getHardwareDiagnostics();
        const summary = typeof diagnostics.lastErrorMessage === 'string' && diagnostics.lastErrorMessage
            ? String(diagnostics.lastErrorMessage)
            : typeof diagnostics.lastConnectionEvent === 'string'
                ? `Diagnostics loaded: ${diagnostics.lastConnectionEvent}`
                : 'Diagnostics loaded.';
        set({
            hardwareDiagnostics: diagnostics,
            hardwareMessage: summary
        });
    },
    async closeShift() {
        const currentShiftId = get().activeShiftId;
        const deps = await getDeps();
        if (currentShiftId) {
            await deps.runtimeStateService?.closeShift(currentShiftId, new Date().toISOString());
        }
        await deps.runtimeStateService?.lockCashierSession(new Date().toISOString());
        set({
            cashierId: null,
            activeShiftId: null,
            cart: [],
            screen: 'login_unlock',
            cashierName: '',
            loginEmail: '',
            lastSyncMessage: 'Shift closed successfully. Please open a new shift to continue.'
        });
    }
}));
