import React, { useState } from 'react';
import { Pressable, Text, TextInput, View } from 'react-native';

export const ShiftOpenScreen = ({
    onOpenShift
}: {
    onOpenShift: (openingCash: number) => void | Promise<void>;
}) => {
    const [openingCash, setOpeningCash] = useState('0');

    return (
        <View style={{ flex: 1, padding: 24, backgroundColor: '#FFFFFF' }}>
            <Text style={{ fontSize: 28, fontWeight: '700', color: '#0F172A' }}>Open Shift</Text>
            <Text style={{ marginTop: 8, fontSize: 14, color: '#475569' }}>Selling stays blocked until local shift-open is recorded.</Text>
            <TextInput
                value={openingCash}
                onChangeText={setOpeningCash}
                keyboardType="numeric"
                placeholder="Opening cash"
                style={{
                    marginTop: 20,
                    borderWidth: 1,
                    borderColor: '#CBD5E1',
                    borderRadius: 8,
                    paddingHorizontal: 14,
                    paddingVertical: 12
                }}
            />
            <Pressable
                onPress={() => onOpenShift(Number(openingCash || 0))}
                style={{ marginTop: 16, backgroundColor: '#0F766E', borderRadius: 8, paddingVertical: 14, alignItems: 'center' }}
            >
                <Text style={{ color: '#FFFFFF', fontWeight: '700' }}>Start Shift</Text>
            </Pressable>
        </View>
    );
};
