import React, { useState } from 'react';
import { Pressable, Text, TextInput, View } from 'react-native';

export const LoginUnlockScreen = ({
    baseUrl,
    companyToken,
    email,
    loading,
    hardwareMessage,
    onUnlock
}: {
    baseUrl: string;
    companyToken: string;
    email: string;
    loading: boolean;
    hardwareMessage: string;
    onUnlock: (input: {
        baseUrl: string;
        companyToken: string;
        email: string;
        password: string;
    }) => Promise<void>;
}) => {
    const [baseUrlValue, setBaseUrlValue] = useState(baseUrl || 'https://pos.dgfy.ph');
    const [companyTokenValue, setCompanyTokenValue] = useState(companyToken || '');
    const [emailValue, setEmailValue] = useState(email || '');
    const [passwordValue, setPasswordValue] = useState('');

    return (
        <View style={{ flex: 1, padding: 24, backgroundColor: '#FFFFFF', justifyContent: 'center' }}>
            <Text style={{ fontSize: 28, fontWeight: '700', color: '#0F172A' }}>Cashier Login / Unlock</Text>
            <Text style={{ marginTop: 8, fontSize: 14, color: '#475569' }}>Backend login uses the same tenant token and bearer-token contract as the web app.</Text>
            <View style={{ marginTop: 16, backgroundColor: '#EFF6FF', borderRadius: 10, borderWidth: 1, borderColor: '#BFDBFE', padding: 12 }}>
                <Text style={{ color: '#1E3A8A' }}>{hardwareMessage}</Text>
            </View>
            <TextInput
                value={baseUrlValue}
                onChangeText={setBaseUrlValue}
                placeholder="Backend base URL"
                autoCapitalize="none"
                style={{
                    marginTop: 20,
                    borderWidth: 1,
                    borderColor: '#CBD5E1',
                    borderRadius: 8,
                    paddingHorizontal: 14,
                    paddingVertical: 12
                }}
            />
            <TextInput
                value={companyTokenValue}
                onChangeText={setCompanyTokenValue}
                placeholder="Company token"
                autoCapitalize="none"
                style={{
                    marginTop: 12,
                    borderWidth: 1,
                    borderColor: '#CBD5E1',
                    borderRadius: 8,
                    paddingHorizontal: 14,
                    paddingVertical: 12
                }}
            />
            <TextInput
                value={emailValue}
                onChangeText={setEmailValue}
                placeholder="Cashier email"
                autoCapitalize="none"
                style={{
                    marginTop: 12,
                    borderWidth: 1,
                    borderColor: '#CBD5E1',
                    borderRadius: 8,
                    paddingHorizontal: 14,
                    paddingVertical: 12
                }}
            />
            <TextInput
                value={passwordValue}
                onChangeText={setPasswordValue}
                placeholder="Password"
                secureTextEntry
                style={{
                    marginTop: 12,
                    borderWidth: 1,
                    borderColor: '#CBD5E1',
                    borderRadius: 8,
                    paddingHorizontal: 14,
                    paddingVertical: 12
                }}
            />
            <Pressable
                disabled={loading}
                onPress={() => void onUnlock({
                    baseUrl: baseUrlValue,
                    companyToken: companyTokenValue,
                    email: emailValue,
                    password: passwordValue
                })}
                style={{ marginTop: 16, backgroundColor: '#1D4ED8', borderRadius: 8, paddingVertical: 14, alignItems: 'center' }}
            >
                <Text style={{ color: '#FFFFFF', fontWeight: '700' }}>{loading ? 'Authenticating...' : 'Login and Unlock POS'}</Text>
            </Pressable>
        </View>
    );
};
